```
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

// Function to count word occurrences
int countWordOccurrences(const string& word, const vector<string>& lines) {
    int count = 0;
    for (const auto& line : lines) {
        // Convert line to lower case for case-insensitive search
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of word in line
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }
    return count;
}

int main() {
    string fileName;
    string word;

    cout << "Enter file name: ";
    cin >> fileName;

    cout << "Enter word to search: ";
    cin >> word;

    // Open file
    ifstream file(fileName);
    if (!file.is_open()) {
        cerr << "Error opening file." << endl;
        return 1;
    }

    // Read file into vector of lines
    vector<string> lines;
    string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }

    // Close file
    file.close();

    // Count occurrences of word in file
    int count = countWordOccurrences(word, lines);

    // Output result
    cout << "Number of occurrences of \"" << word << "\" in file \"" << fileName << "\": " << count << endl;

    return 0;
}
```

Note: This program assumes that the input file does not contain empty lines. If empty lines are present, you can modify the `getline` loop to skip empty lines using `if (!line.empty()) lines.push_back(line);`.
